import { ref, computed } from 'vue';
import { useStore } from 'vuex';
import { format, parseISO } from 'date-fns';
import { calculateDateRange } from '@/utils/dateRangeUtils';
export default {
  name: 'DateRangeSelector',
  props: {
    dateRange: {
      type: Object,
      default: () => ({
        from: null,
        to: null
      })
    }
  },
  emits: ['update:modelValue'],
  setup(props, {
    emit
  }) {
    const store = useStore();
    const menu = ref(false);
    const selectedRange = ref('ytd');
    const dateFrom = ref(props.dateRange.from);
    const dateTo = ref(props.dateRange.to);
    const effectiveCurrentDate = computed(() => store.state.effectiveCurrentDate);
    const dateRangeOptions = computed(() => {
      const currentYear = new Date(effectiveCurrentDate.value).getFullYear();
      return [{
        title: `${currentYear}YTD`,
        value: 'ytd'
      }, {
        title: 'Last 1 Month',
        value: 'last1m'
      }, {
        title: 'Last 3 Months',
        value: 'last3m'
      }, {
        title: 'Last 6 Months',
        value: 'last6m'
      }, {
        title: 'Last 12 Months',
        value: 'last12m'
      }, {
        title: 'Last 3 Years',
        value: 'last3y'
      }, {
        title: 'Last 5 Years',
        value: 'last5y'
      }, {
        title: 'All-time',
        value: 'all_time'
      }];
    });
    const displayDateRange = computed(() => {
      if (dateFrom.value && dateTo.value) {
        return `${format(parseISO(dateFrom.value), 'dd MMM yyyy')} - ${format(parseISO(dateTo.value), 'dd MMM yyyy')}`;
      }
      return 'Select Date Range';
    });
    const handlePredefinedRange = value => {
      const dateRange = calculateDateRange(value, effectiveCurrentDate.value);
      dateFrom.value = dateRange.from;
      dateTo.value = dateRange.to;
    };
    const applyDateRange = () => {
      emit('update:modelValue', {
        from: dateFrom.value,
        to: dateTo.value
      });
      menu.value = false;
    };
    return {
      menu,
      selectedRange,
      dateFrom,
      dateTo,
      dateRangeOptions,
      displayDateRange,
      handlePredefinedRange,
      applyDateRange
    };
  }
};
